bool StructTraits<::new_tab_takeover::mojom::AutocompleteMatch::DataView, ::new_tab_takeover::mojom::AutocompleteMatchPtr>::Read(
    ::new_tab_takeover::mojom::AutocompleteMatch::DataView input,
    ::new_tab_takeover::mojom::AutocompleteMatchPtr* output) {
  bool success = true;
  ::new_tab_takeover::mojom::AutocompleteMatchPtr result(::new_tab_takeover::mojom::AutocompleteMatch::New());
  
      if (success && !input.ReadContents(&result->contents))
        success = false;
      if (success && !input.ReadDescription(&result->description))
        success = false;
      if (success && !input.ReadDestinationUrl(&result->destination_url))
        success = false;
      if (success && !input.ReadIconUrl(&result->icon_url))
        success = false;
      if (success && !input.ReadImageUrl(&result->image_url))
        success = false;
      if (success)
        result->allowed_to_be_default_match = input.allowed_to_be_default_match();
  *output = std::move(result);
  return success;
}

